function convertToSlug(Text){return Text.toLowerCase().replace(/[^\w ]+/g,"").replace(/ +/g,"-")}function anchorfy(){var els=document.querySelectorAll("h1, h2, h3, h4, h5, h6"),currentPage=location.pathname;els.forEach((function(el){var slug=convertToSlug(el.innerText),path=currentPage+"#"+slug;el.setAttribute("id",slug),el.outerHTML="<a href="+path+">"+el.outerHTML+"</a>"}));var id=location.hash.substr(1),element=document.getElementById(id);if(null!=element){const yOffset=-20,y=element.getBoundingClientRect().top+window.pageYOffset+yOffset;window.scrollTo({top:y,behavior:"smooth"})}}null!=document.getElementById("dynamic-content-wrapper")&&window.addEventListener("load",anchorfy);